import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·18","description":"易小帖 - 卷五·18","frontmatter":{"title":"卷五·18","description":"易小帖 - 卷五·18"},"headers":[],"relativePath":"zh/classics/yixiaotie/140.md","filePath":"zh/classics/yixiaotie/140.md"}'),o={name:"zh/classics/yixiaotie/140.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·18",tabindex:"-1"},[r("卷五·18 "),e("a",{class:"header-anchor",href:"#卷五·18","aria-label":"Permalink to “卷五·18”"},"​")],-1),e("p",null,"答：天地俱有生成萬物之理，雖言生，而成在其中。然而有生必有成，成亦生也。如人物之生，皆不能以生該成。人不生於衣食，然無衣食則不生，故又曰衣食者人之生也。物可無衣矣，然無食則不生。植物可無衣並無食矣，然無氣之寒燠如衣，雨露之滋養如食，則又不生。是物之成者，亦即其生之者也。是以天地可各分生成，有從陰生者，有從陽生者，黃鳥鳴春，蟋蟀吟秋，菱蒂結於夜，槿花落於晝，凡物皆然。其從陰陽生者，亦即以陰陽成之。故以易大生廣生言之，則天地皆生，以中庸悠久成物言之，則天地皆成。若夫天三生而地三成，則究竟天主生而地主成，其主客多寡之數，原自有別，猶之陽主生，而陰主殺，雖陽有時殺，陰有時生，而其為主客多寡不可沫也。如謂水木土何以生於天，火金何以生於地，則其中有至理焉。天之生水，陽生陰也。故水居陰方，而抱陽質，以北方之卦而為中男，後儒所謂水外陰而中陽者是也。地之生火，陰生陽也。故火居陽方，而抱陰質，以南方之卦而為中女，後儒所謂火外陽而中陰者是也。天之生木，陽生陽也。木陽位陽質，以東方長男而生陽火，無非陽也。地之生金，陰生陰也。金陰位陰質，以西方少女而生陰水，無非陰也。至於土本地也，然不謂之地而謂之土，惟其本地則地不得生而天生之，惟不謂之地而謂之土，則不生於地而得成於地，此固合陰陽之氣以為質者。天數地數，皆全彚於中，而共為生成。其在四行之後者，以生成大數得此而全，非謂生成遞行以此為殿。蓋火不必後於水，木亦不必後於火，生成有先後，五行無早晚也。至謂水火木金土何以必配一二三四五，則《洪範》曰：一曰水，水數一也。乃易以坎為水，以北方之卦當之，而曰天一生水於北，是五位相得。所雲天一者，正天地生水之數也。水必一也。《洪範》曰：二曰火，火數二也。乃易以離為火，以南方之卦當之，而曰地二生火於南，是五位相得。所雲地二者，正天地生火之數也。火必二也。至於三曰木，而易以東方之震當之，曰天三生木於東。四曰金，而易以西方之兌當之，曰地四生金於西。五曰土，而易以中央之土當之，曰天五生土於中，是五位相得。所雲天三地四天五者，皆天地生木金土之數，而木之必三，金之必四，土之必五，原本自然，非有強也。顧人第知一二三四五之可疑，而不知六七八九十之更當審也。《洪範》有生數而無成數，故有一二三四五而無六七八九十。且有天地生五行之數，而無五行相生之數。故但有五位之相得，而無五位之相合。夫一二三四五，此五位也，此相得者也，而一合五而成六，二合五而成七，三合五而成八，四合五而成九，五合五而成十，則相合也。以五生五，即以五合五，所謂成也。乃即此成五而生在其中，何也？一之生水，天之生水，也有六之成水而金之生水見焉，何也？六金數也，西北之數也，水以金成，然即以金生也。二之生火，地之生火，也有七之成火而木之生火見焉，何也？七木數也，東南之數也，火以木成，然即以木生也。至於三之生木，天生木也。木非水不生，而艮八居東北，以水合土而生木於東，謂之水生木四之生金。地生金也，金非土不生，而坤九居西南以火合土而生金於西（火無土則尅金矣），謂之土生金至五之生土，則有十以成之，而木三與火二為五，金四與水一為五而合之，而總成為十。是五行之生，《洪範》有之。五行合生成，而即兼相生之數。惟大衍有之。大衍與五行原相為表裡，而文王六十四卦中從無五行。夫子易有太極章亦無五行，故曰易卦無五行，太極配五行無理，並非曰易無五行也。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
